  doctor_name: z.string().optional(),
  hospital_name: z.string().optional(),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Date must be YYYY-MM-DD').optional(),
  diagnosis: z.string().optional(),
